self.KB_CONTENT["card:779257"]={"id":"card:779257","ty":"card","sourceId":"779257","title":"『成本開帳/調整單建立作業(IDL)』中的『專案代號 (TK021)』為何？","ver":"GP4以上","topic":"品號","keywords":["品號","專案","開帳"],"y":"other","answer":"* [F3]品號專案資料查詢(INVLD-01)。* [F2]專案代號資料查詢(CMSNB-02)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
