self.KB_CONTENT["field:752016"]={"id":"field:752016","ty":"field","sourceId":"752016","title":"列印時依借貸方排列","ver":"iGP","topic":"","keywords":[],"job":"會計參數設定作業","code":"MC003","answer":"* 若勾選，則列印會計傳票時會依借貸之順序列印（借方印完再印貸方）。","file":"fields.jsonl"};
