self.KB_CONTENT["field:780774"]={"id":"field:780774","ty":"field","sourceId":"780774","title":"匯出入資料檔名","ver":"GP4以上","topic":"","keywords":[],"job":"資料匯出入欄位設定作業","code":"TE006","answer":"* 例如：「檔案代號」輸入「ACTMB」，則預設「匯出入資料檔名」為「ACTMB.xls」。","file":"fields.jsonl"};
